insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-36651','course','Гид по миру крепкого алкоголя',null,'{"id":"guru-36651","title":"Гид по миру крепкого алкоголя","shortTitle":"Гид по миру крепкого алкоголя","coverLabel":"Гид по миру крепкого алкоголя","description":"Виды крепких напитков и проверка знаний об алкоголе.","kind":"course","brand":"90-е","departments":["Зал","Бар","Кухня","Арт","Кальян","Руководитель"],"positions":[],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Водка","text":"История Водки\n\nВодка – национальный алкогольный напиток России. Она ассоциируется именно с нашей страной, хотя производят её и в других государствах мира. Водка – один из древнейших крепких алкогольных напитков на Земле. \n\nВ Москву этиловый спирт привезли в 1386 году представители генуэзского посольства. Его презентовали князю Дмитрию Донскому, как aqua vitae (живую воду). Об этом говорится в записках Музея русской водки (Москва, РФ). Наши предки продукт оценили, но из-за чрезмерных «оборотов» предпочли перед употреблением разводить водой. Так идея разбавления водой крепкого дистиллята легла в основу производства русской водки.\n\nПрародителем современной водки в России стало «хлебное вино». Этот зерновой дистиллят, появившийся в XV веке, изначально имел крепость около 38% и часто назывался «полугаром», так как при поджигании выгорала ровно половина напитка.\n\nВажную роль в научном обосновании производства водки сыграл Дмитрий Иванович Менделеев. В 1865 году он защитил диссертацию на тему «О соединении спирта с водою», в которой подробно исследовал физико-химические свойства смесей этилового спирта с водой. В своей работе учёный показал, что оптимальной по физическим и органолептическим свойствам является смесь, в которой содержание спирта составляет около 40% по объёму. Именно эта работа легла в основу стандартизации крепости русской водки.\n\nС первого взгляда водка может показаться несложным напитком, ведь в основе ее производства лежит простой принцип – максимальная чистота конечного продукта. Однако этот напиток не так прост, ведь его изготовление требует высочайшей технологии, современного оборудования, большого опыта и пристального внимания.\n\nВодка является лучшей основой для приготовления коктейлей, ведь сама по себе не имеет вкуса и придаёт лишь нужную крепость. Она прекрасно сочетается с любыми ингредиентами, используемые в приготовлении коктейлей (ликеры, сиропы, соки, пюре и т. д.).\n\nПроизводство\n\nПолучение браги. Зерно перемалывают в муку, смешивают ее с водой, нагревают и варят под давлением. В процессе разваривания крахмал, содержащийся в сердцевине зерна, превращается в сахар. Полученную смесь охлаждают, перекачивают в бродильный чан и добавляют дрожжи. В результате брожения получается брага крепостью 9%. \n\nПерегонка. Брагу подвергают перегонке в колоннах непрерывного действия, получая в результате нейтральный спирт крепостью 93–96%.\n\nФильтрация. Процесс фильтрации водочного спирта был придуман в России в 19 веке. Сегодня производители используют различные типы фильтров, например, древесный уголь или кварцевый песок. После фильтрации водочный спирт разбавляют водой до нужной крепости. Качество воды имеет большое значение, и производители уделяют этому вопросу особое внимание. Как правило, крепость готового продукта – не менее 40%. После разбавления водку разливают по бутылкам.\n\nКлассификация\n\nОсновной компонент водки – этиловый спирт. Он попадает под обязательные требования стандартизации. Как правило, водку принято классифицировать в зависимости от того, из спирта какой категории она произведена. Категория спирта обязательно указывается на контрэтикетке бутылки.\n\nСпирт «Альфа».\n\nСырьем для его производства служит только зерно: пшеница или рожь, иногда их смесь. В этом состоит основное преимущество спирта \"Альфа\" над остальными водочными спиртами, так как в их производстве допускается использование картофеля. Дело в том, что картофель содержит пектиновые вещества, которые в процессе переработки превращаются в метанол. Именно спирт категории \"Альфа\" является основой водки премиум класса. Он проходит очистку в несколько этапов. Считается спиртом новейшего, пятого поколения.\n\nСпирт \"Люкс\" изготавливается из пшеничного зерна с добавлением картофеля. Согласно ГОСТу, количество крахмала картофеля в смеси не должно превышать 35%. Фильтрация спирта данной категории выполняется в несколько этапов. Спирт \"Люкс\" используется для водок сегмента премиум, которые всегда позиционируются как продукт, изготовленный по уникальной рецептуре.\n\nСпирт \"Экстра\".\n\n Производится из пшеничной зерна и картофеля. В данном случае ГОСТ ограничивает содержание картофельного крахмала в смеси 65%. \"Экстра\" — это спирт широкого потребления. До премиум-сегмента он не дотягивает, но является вполне качественным.\n\nСпирт высшей очистки.\n\nНесмотря на претенциозное название, именно он проходит не самую тщательную фильтрацию и содержит наибольшее количество микропримесей, оставшихся после ректификации, - так называемых \"сивушных\" веществ. Это Спирт невысокой качества и низшего рыночного сегмента.\n\nКультура потребления\n\nТемпература подачи водки остается спорным вопросом. В большинстве стран мира водку очень сильно охлаждают (до -18°). Между тем профессиональные дегустаторы утверждают, что оптимальная температура ее подачи, позволяющая почувствовать нюансы вкуса, составляет +5-С (достигается в холодильнике).\n\nКак правило, водку подают в рюмках, хорошо охлажденных в морозильной камере. Однако в Америке, где водку иногда называют \"белым виски\", достаточно распространена ее подача в бокале Олд Фэшн с кубиками льда.\n\nНесмотря на высокую крепость, водка может быть неплохим аперитивом. \n\nКроме того, это гастрономический алкоголь, который сочетается с различными блюдами, особенно русской кухни: блинами, щами, пельменями, икрой.  Она прекрасно дополнит мясные блюда, приготовленные на открытом огне или в печи, сырные закуски, соленья, икру, маринованные грибы, квашеные овощи и фрукты или свежие овощи.","images":["assets/remaining-courses/guru-36651-77867-0.jpg","assets/remaining-courses/guru-36651-77867-1.jpg","assets/remaining-courses/guru-36651-77867-2.jpg","assets/remaining-courses/guru-36651-77867-3.jpg"],"links":[],"id":"77867"},{"title":"Джин","text":"История Джина\n\nДжин берет своё начало от женевера – голландского зернового дистиллята с ароматом можжевельника. Английские солдаты попробовали женевер в 17 веке, во время Тридцатилетней войны, и за способность поднимать боевой дух окрестили его «Голландской храбростью». А еще им понравились согревающие свойства женевера. После войны его стали активно производить и продавать в англии, правда, по несколько иной технологии и под сокращенным названием – Джин. В первой половине 18 века страна пережила настоящий бум популярности джина. В Англии он стал первым крепким алкоголем, доступным самым широким народным массам, и о его качестве мало кто беспокоился. Лишь к середине 19 века джин постепенно превратился в тот напиток, который знаем мы. Сегодня его выпускают во многих странах, так как особых ограничений в производстве джина нет.\n\nПроизводство\n\nСуществуют два основных вида производства:\n\nДистилляция (Перегонка): Путем дистилляции получают премиальные марки джина. Спирт разбавляют водой до 45%, полученный раствор наливают в перегонный аппарат, добавляют ботаникалы и проводят дистилляцию. Во время перегонки испаряемый спирт насыщается ароматами трав и специй. Полученный ароматизированный спирт (его крепость составляет около 80%) разбавляют водой и разливают по бутылкам. По законам Англии, крепость джина не может быть менее 37,5% и выше 47,3%.\n\nСмешивание: Как правило, этим способом производят более демократичные марки джина. Для начала изготавливают так называемую «джиновую эссенцию». Ее получают путем сильной ароматизации небольшой партии спирта. В дальнейшем эту эссенцию смешивают с чистой водой и оставшимся чистым спиртом.\n\nКлассификация\n\nСовременные виды джина:\n\nGin (Джин): Производится исключительно на основе нейтрального этилового спирта с использованием можжевеловых ягод. Характерный аромат достигается за счет повторной дистилляции с растительными компонентами. Зачастую такой джин производят методом смешивания, он не отличается особым качеством.\n\nDistilled Gin: Отличается двойной перегонкой: сначала получают спирт крепостью не менее 96%, затем повторно дистиллируют с натуральными растительными ингредиентами. Хотя можжевельник остается доминирующим ароматом, добавление цитрусовых корок или кориандра во вторую перегонку создает уникальные вкусовые профили. Так же после процесса дистилляции могут быть добавлены различные настои и эссенции, для придания особых органолептических свойств напитку. Именно так появляются популярные вариации вроде лимонного или цветочного джина.\n\nLondon Dry Gin: Самый строгий стандарт: запрещены любые добавки после дистилляции, включая сахар (максимально допустимо 0,1 г/л). Сухой вкус с ярким можжевельником делает его идеальной основой для мартини. Можно считать, что London Dry Gin является самым «честным» джином.\n\n \n\nИсторические виды Джина:\n\n \n\nPlymouth Gin: Это одновременно и марка джина, и его разновидность. Единственная винокурня, производящая Плимут джин, называется «Black Friars Distillery». В отличии от London Dry название плимутского джина несет в себе привязку к региону производства. Джин из Плимута изготавливают путем дистилляции. Его разбавляют местной водой, которая придает ему мягкость. Полный состав джина держится в строжайшей тайне, известно только, что в качестве основного сырья используется преимущественно зерновой (пшеничный) спирт.\n\n \n\nOld Tom Gin: Традиционный английский джин, подслащенный сахарным сиропом. Он пользовался огромной популярностью и стал предшественником сегодняшнего джина. Его название возникло от того, что в 18 веке такой джин продавался в деревянном аппарате в форме кота (Том – самая популярная кличка для кота того времени). Покупатель клал деньги в рот кота, и джин вытекал из трубы, скрытой в его лапе.\n\n \n\nSloe Gin: Sloe Gin это разновидность джина с добавлением терновых ягод. В отличие от классического джина Sloe Gin имеет среднюю крепость - около 30 процентов имеет характерный рубиново-красный оттенок. Этот напиток больше похож на ликер, но его принято включать в классификацию джинов.\n\n \n\nYellow Gin: Желтый джин – напиток цвет которого варьируется от прозрачно-желтоватого до темно-желтого. Характерный оттенок ему придает выдержка в различных деревянных бочках (как правило, в бочках из-под хереса) и добавление натурального растительного сырья. Такой джин встречается крайне редко и стоит крайне дорого.\n\nКультура потребления\n\nДжин принято подавать охлажденным до 4-7°C в небольших рюмках. В чистом виде его следует пить залпом, а в сочетании с другими напитками – растягивать удовольствие, наслаждаясь каждым глотком уникального напитка. Это позволит раскрыть вкус джина и оценить его неповторимый шарм. Чаще всего джин смешивают с тоником для раскрытия его вкуса и качеств, большинство дегустаций проходит именно в таком формате.\n\n \n\nДорогостоящий джин с изысканным вкусом принято пить в чистом виде, хотя напиток обладает достаточно высокой крепостью. Такой вариант подойдет только истинным ценителям, которые хотят насладиться незабываемыми органолептическими качествами джина. Джин является превосходной основой для коктейлей, он хорошо сочетается со многими ингредиентами такими как: ягоды, цитрусы, овощи и различные фрукты.\n\n \n\nДжин прекрасно сочетается с различными закусками и напитками. К нему подойдут лимонный, грейпфрутовый и клюквенный соки, а также оливки, сыр, копченый лосось, орехи и ягоды.","images":["assets/remaining-courses/guru-36651-123958-0.jpg","assets/remaining-courses/guru-36651-123958-1.jpg","assets/remaining-courses/guru-36651-123958-2.jpg","assets/remaining-courses/guru-36651-123958-3.jpg"],"links":[],"id":"123958"},{"title":"Текила","text":"История Текилы\n\nТекила – единственный в своем роде напиток. Он настолько непохож на другие, что можно подумать, будто его перегнали на другой планете. Его ароматы и текст ура не имеют аналогов в мире алкоголя. Именно по этой причине постоянно ширится круг ценителей текилы.\n\nЛегенда гласит, что история текилы нача лась у подножия вулкана, когда молния ударила в поле агавы. Под действием жара сок одного из растений закипел, потом забродил и в результате превратился в чудесный нектар, который ацтеки приняли за дар небес.\n\nСуществует несколько версий относительно происхождения слова «текила». В народе считается, что испанские конкистадоры назвали напиток текилой как производное от слова «тетилья» (сосок), поскольку они заметили, что лучшие агавы росли по склонам небольшой горы, очертаниями странно напоминающей женскую грудь, – там, где теперь расположен город Текила. Согласно научной версии город Текила, давший название напитку, получил свое имя от индейского племени, относящегося к народу нахуатль, на языке которого слово «текила» означало что-то вроде места сбора урожая.\n\nПроизводство\n\nСырье: Основным сырьем для производства текилы служит особая голубая агава (Agave Tequilana сорта Blue Weber). Она растет под палящими лучами солнца, достигая необходимой зрелости через 7-8 лет. Сборщиков урожая называют «химадорами». Они удаляют с отрубленных агав колкие листья, оставляя только сердцевины растений, которые похожи на гигантские ананасы. За это мексиканцы называют их piñas. Такая сердцевина весит от 30 до 80 килограммов.\n\nБрожение: Сердцевины агав разрубают в зависимости от размера пополам или на четыре части. Затем их запекают в больших печах, чтобы как можно больше крахмала превратилось в сахар. Готовую агаву измельчают, выжимая сладкий, вязкий, темный сок, в который добавляют воду для облегчения брожения. Брожение длится от 2 до 5 дней. Обычно для его усиления добавляют дрожжи. Некоторые производители используют метод закваски применяемый для бурбона и рома.\n\nПерегонка: Раньше для текилы широко использовались коньячные аппараты и аламбики, применяемые для виски. Сегодня производители предпочитают перегонные аппараты из нержавеющей стали менее дорогие и более практичные в уходе, но функционирующие по традиционному принципу двойной перегонки. После первой дистилляции они дают спиртное ordinario крепостью 28%, а после второй – текилу крепостью 55%.\n\nВыдержка: Текила может быть выдержана либо в старых бочках из-под бурбона, хереса или порто, либо в новых дубовых бочках. Спиртное агавы не обладает высоким потенциалом к старению. К тому же сухой и жаркий климат Мексики не благоволит медленному дозреванию напитка. Так, «доля ангелов» здесь достигает 10% в год. Для сравнения: в Шотландии она составляет 4%. Поэтому выдержка текилы чаще всего не превышает 6 лет. После выдержки в случае необходимости крепость текилы снижают, добавляя в нее воду, и разливают по бутылкам.\n\nКлассификация\n\nПо содержанию голубой агавы:\n\nОсновные категории: Tequila 100% de Agave (или 100% puro de agave)\nСостав: Изготавливается исключительно из сока голубой агавы (Weber blue agave).\nОсобенности: Премиальный продукт, который бутилируется только внутри Мексики.\nВкус: Полнотелый, передает травяные и цитрусовые ноты агавы.\nМаркировка: На этикетке обязательно указано «100% de agave».\n\nTequila Mixta (смешанная):\n\nСостав: Содержит не менее 51% сахаров голубой агавы, остальное (до 49%) — спирты из других источников (сахарный тростник, кукурузный сироп).\nОсобенности: Более доступная по цене, часто экспортируется наливом и разливается за пределами Мексики.\nМаркировка: Если на бутылке нет надписи «100% de agave», это «миксто».\nПо выдержке: Blanco (бланко), или Plata (плата) - бесцветная текила, которую разливают по бутылкам сразу после перегонки. Или ее могут выдержать не более двух месяцев в стальных чанах или дубовых бочках. Ее также могут называть White или Silver.\nReposado (Репосадо) - так называется текила, которая выдержана в дубовых бочках не менее 2 месяцев и не более одного года. Это придает ей легкий янтарный оттенок, который усиливают добавлением карамели (не более 1% от общего объема).\n\nAnejo (Аньехо) - эта текила стареет не менее одного года и не более трех лет в дубовых бочках емкостью не более 600 литров.\n\nExtra Anejo (Экстра Аньехо) - эта текила стареет не менее трех лет в дубовых бочках. \n\nКультура потребления\n\nКак говорят эксперты, текила — универсальный напиток. Хорош как в чистом виде, так и в составе коктейлей.\n\nВ самой Мексике текилу пьют из небольших стопок, сильно не охлаждая напиток. Ее не закусывают и не заедают, несмотря на высокую крепость. Впрочем, в некоторых регионах страны популярен следующий способ употребления спиртного — текила в сочетании с сангритой. Пить в таком виде высокоградусный алкоголь куда приятнее. В одну стопку наливается текила, в другую — сангрита. И тут все просто — сначала выпивается рюмка алкоголя, а потом следует порция безалкогольного микса.\n\nА за пределами Мексики распространен другой способ употребления напитка — в сочетании с солью и лаймом. Считается, что это трио создает идеальный баланс вкуса. И к тому же, минимизирует риски обжечь гортань при употреблении крепкого спиртного. Сначала соль, потом текила, затем долька цитрусового.","images":["assets/remaining-courses/guru-36651-123961-0.jpg","assets/remaining-courses/guru-36651-123961-1.jpg","assets/remaining-courses/guru-36651-123961-2.jpg","assets/remaining-courses/guru-36651-123961-3.jpg"],"links":[],"id":"123961"}],"outline":[{"type":"lesson","title":"Водка","lessonIndex":0},{"type":"test","title":"Тест водка"},{"type":"lesson","title":"Джин","lessonIndex":1},{"type":"test","title":"Тест джин"},{"type":"lesson","title":"Текила","lessonIndex":2},{"type":"test","title":"Тест текила"}],"testIds":["80505","105355","105354"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('guru-43399','course','Вдохновляющий менеджмент: эффективные стратегии мотивации сотрудников в ресторане',null,'{"id":"guru-43399","title":"Вдохновляющий менеджмент: эффективные стратегии мотивации сотрудников в ресторане","shortTitle":"Вдохновляющий менеджмент: эффективные стратегии мотивации сотрудников в ресторане","coverLabel":"Вдохновляющий менеджмент: эффективные страт…","description":"Мотивация команды и практики работы с сотрудниками.","kind":"course","brand":"90-е","departments":["Руководитель","Зал","Бар"],"positions":["Руководитель","Администратор","Старший бармен"],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Введение","text":"Основы мотивации\n\nРесторанный бизнес является одной из наиболее динамичных и требовательных отраслей. Он предполагает работу с многообразием гостей, постоянное соблюдение стандартов и строгие сроки. Однако, безусловно, самым ценным активом в ресторанной индустрии являются сотрудники.\n\nМотивация - это ключевой элемент в управлении персоналом. Эффективная мотивация помогает не только повысить уровень сервиса и удовлетворенности клиентов, но и улучшить общую производительность сотрудников. Она может вдохновить команду, создать позитивную атмосферу в ресторане и помочь достичь поставленных целей.\n\nДавайте начнем с определения мотивации. В контексте управления персоналом, мотивация - это внутренний или внешний стимул, который побуждает сотрудника к выполнению определенных действий или достижению определенных результатов.\n\nОна может проявляться как в желании удовлетворить основные потребности, такие как еда и жилье (физиологические потребности), так и в стремлении к достижению личных или профессиональных целей.","images":["assets/remaining-courses/guru-43399-101481-0.jpg","assets/remaining-courses/guru-43399-101481-1.jpg"],"links":[],"id":"101481"},{"title":"Основы мотивации в ресторанной индустрии","text":"Особая роль мотивации\n\nВ ресторанной индустрии, где работники ежедневно взаимодействуют с гостями, мотивация играет особенно важную роль. Каждый гость имеет высокие ожидания, и успешная команда сотрудников - это то, что делает ресторан процветающим и привлекательным.\n\nВнутренние и внешние мотиваторы присущи всем людям. Внутренние мотиваторы - это личные амбиции, желания и ценности сотрудников, которые побуждают их к лучшей  работе. Внешние мотиваторы, с другой стороны, могут включать в себя финансовые вознаграждения, поощрения и признания со стороны руководства.\n\nВ нашем курсе мы подробнее изучим некоторые теории мотивации и методы ее практического применения в ресторанной деятельности.\n\nВы узнаете, какие факторы могут вдохновить ваших сотрудников и какие инструменты можно использовать для создания позитивной рабочей атмосферы.\n\nПонимание и эффективное управление мотивацией - это навык, который поможет вам успешно управлять персоналом ресторана и добиваться выдающихся результатов. \n\nПирамида мотивации\n\nОдин из ключевых аспектов успешной мотивации - это понимание разнообразных уровней, на которых мотивация может проявляться. Эти уровни были систематизированы А. Маслоу и стали известными как \"Пирамида потребностей Маслоу.\"\n\nПо пирамиде Маслоу, мотивация начинается с физиологических потребностей, таких как еда и жилье, и двигается вверх к более высоким уровням, включая потребность в безопасности, социальной принадлежности, самоуважении и самореализации. Понимание, на каком уровне мотивации находится сотрудник, может помочь менеджеру создать соответствующую мотивационную стратегию.\n\nПирамида мотивации\n\nВ ресторанной индустрии, это означает, что менеджеры должны быть готовы удовлетворить физиологические потребности сотрудников, такие как предоставление перерывов и еды, а также обеспечивать безопасность на рабочем месте. Однако, успешная мотивация также включает в себя удовлетворение более высоких потребностей, таких как социальная принадлежность и самоуважение.\n\nПонимание, какие уровни мотивации актуальны для конкретного сотрудника, и насколько сильно действуют внутренние и внешние мотиваторы, может помочь менеджерам адаптировать свой подход и создать более эффективные мотивационные стратегии.","images":["assets/remaining-courses/guru-43399-101482-0.jpg","assets/remaining-courses/guru-43399-101482-1.jpg","assets/remaining-courses/guru-43399-101482-2.jpg","assets/remaining-courses/guru-43399-101482-3.jpg"],"links":[],"id":"101482"},{"title":"Связь мотивации с производительностью","text":"Понимание этих методов и их практическое применение в ресторанной деятельности может помочь увеличить производительность сотрудников и улучшить обслуживание гостей","images":["assets/remaining-courses/guru-43399-101483-0.jpg"],"links":[],"id":"101483"},{"title":"Теории мотивации","text":"Теория Герцберга\n\nВ этом уроке мы рассмотрим основные теории мотивации, которые помогут вам лучше понять, что движет сотрудниками, какие факторы влияют на их мотивацию, и как вы можете применить это в контексте вашей работы.\n\nФредерик Герцберг, американский психолог, предложил теорию двух факторов, также известную как теория \"удовлетворение - неудовлетворение\". Эта теория позволяет понять, что именно мотивирует сотрудников и какие факторы влияют на их удовлетворенность работой.\n\nОсновные принципы теории Герцберга:\n\n1. Факторы удовлетворения: Герцберг связывает их с тем, что сотрудники считают важным и мотивирующим в своей работе. В ресторанной индустрии, такими факторами могут быть чувство выполнения плана, признание коллегами, возможность роста и развития, а также интересные задачи.\n\n2. Факторы неудовлетворения: обычно они  связаны с недовольством и негативными эмоциями сотрудников. В ресторанной индустрии, к факторам неудовлетворения можно отнести недостаточное вознаграждение за выполненные задачи, неприятные условия труда, отсутствие признания и чувство несправедливости.\n\nКлючевая идея теории Герцберга заключается в том, что факторы удовлетворения и неудовлетворения независимы друг от друга. Это означает, что увеличение факторов удовлетворения (например, предоставление возможностей для развития и признания) может увеличить удовлетворенность сотрудников, но не обязательно уменьшить неудовлетворение.\n\nКак менеджеры ресторана могут применять теорию Герцберга? Важно понимать, что удовлетворение сотрудников - это не просто отсутствие неудовлетворения. Ресторанные менеджеры могут работать над созданием более удовлетворяющей среды для своих сотрудников, предоставляя им возможности для саморазвития, признания и чувство ценности в команде.\n\nНа практике это может включать в себя проведение индивидуальных бесед, определение профессиональных целей сотрудников и предоставление возможностей для обучения и развития. \n\nТеория ожидания Врума\n\nТеория ожидания Врума - это теория мотивации, разработанная Виктором Врумом еще  в 1964 году. Она предполагает, что мотивация сотрудников зависит от ожидания, что усилия, приложенные для достижения определенной цели, приведут к желаемому результату, и ценности этого результата для сотрудника. Важные концепции этой теории включают:\n\n1. Ожидание (Expectancy): Отражает веру сотрудника в то, что его усилия приведут к достижению цели. Если сотрудник считает, что его усилия бесполезны, его мотивация будет низкой.\n\n2. Инструментальность (Instrumentality):Инструментальность оценивает, насколько успешное достижение цели приведет к желаемым вознаграждениям. Если сотрудник сомневается в том, что его успешные действия будут вознаграждены, его мотивация снижается.\n\n3. Значимость вознаграждения (Valence):Значимость вознаграждения определяет, насколько сотрудник ценит то, что получит, если достигнет цели. Если вознаграждение не имеет для него значения, мотивация будет низкой.\n\nУбедитесь, что сотрудники понимают, что их усилия важны и могут привести к достижению успешных для них результатов. Предоставьте им ясные цели и поддержку в достижении этих целей. Проследите, что сотрудники видят прямую связь между своими действиями и вознаграждениями. Поясните, как достижение целей влияет на их карьерное развитие, вознаграждение или признание.\n\nНапример:\n\nПредставим, что в ресторане принята  следующая система: если официант продает установленное количество дополнительных блюд за месяц или получает положительные отзывы от гостей,то он получает бонус к своей зарплате и возможность совершенствовать свое развитие. (например может быть приглашен на специальные тренинги  для повышения профессиональных навыков или занесен в кадровый резерв.)\n\nПомимо обычной системы бонусов, которая применяется часто, вы  можете построить мотивацию основываясь на построении карьеры сотрудников: например разработать карьерную карту  для каждой должности, для наглядного отображения сотрудникам что их ждет за определенные достижения. Рассмотрим пример карьерной карты для должности официант:\n\nТакая система мотивации позволяет сотрудникам видеть прямую связь между своими действиями (качественное обслуживание, работа с гостями) и получением вознаграждений. Таким образом, достижение целей влияет на их карьерное развитие (повышение квалификации), вознаграждение (бонусы) и признание (уважение со стороны руководства и коллег). Это мотивирует сотрудников к более эффективной работе и создает позитивный рабочий атмосферу.\n\nТеория ожидания Врума подчеркивает важность прозрачности, связи усилий и результатов, а также адаптации мотивационных стратегий к индивидуальным потребностям сотрудников\nВ заключении\n\nВ заключение- теории мотивации помогают нам понять чего хотят наши сотрудники, что не всегда отсутствие плохих условий работы может быть позитивной мотивацией, и что все сотрудники должны понимать и видеть четкую взаимосвязь между своими действиями и последствиями. которые их ожидают. Понимание данных теорий и их применение может помочь создать мотивированную и продуктивную команду, что важно в ресторанной индустрии с высокой конкуренцией и требовательными клиентами.\n\nПрактическое задание к модулю: Вы должны выбрать одну из теорий мотивации (Герцберга, ожидания Врума) и применить ее к конкретной ситуации в ресторане. Разработайте письменный план- какие шаги можно предпринять для улучшения мотивации сотрудников в соответствии с выбранной теорией.","images":["assets/remaining-courses/guru-43399-101484-0.jpg","assets/remaining-courses/guru-43399-101484-1.jpg","assets/remaining-courses/guru-43399-101484-2.jpg","assets/remaining-courses/guru-43399-101484-3.jpg","assets/remaining-courses/guru-43399-101484-4.jpg","assets/remaining-courses/guru-43399-101484-5.jpg","assets/remaining-courses/guru-43399-101484-6.jpg","assets/remaining-courses/guru-43399-101484-7.jpg","assets/remaining-courses/guru-43399-101484-8.jpg"],"links":[],"id":"101484"},{"title":"Практические инструменты мотивации персонала","text":"Завершая этот модуль, мы видим, что эффективная мотивация сотрудников в ресторанной индустрии включает в себя разнообразные инструменты, от финансовых вознаграждений и признания до развития навыков и улучшения рабочей среды. Понимание и применение этих инструментов могут помочь в создании успешного ресторанного бизнеса и долгосрочных отношений с сотрудниками.\n\nПрактическое задание: Вы  должны разработать мотивационный план для своего ресторана, включая методы вознаграждения, систему признания, обучение и улучшение рабочей среды. Они также должны определить меры успеха для оценки эффективности плана.","images":["assets/remaining-courses/guru-43399-101485-0.jpg"],"links":[],"id":"101485"},{"title":"Оценка и управление мотивацией","text":"Мониторинг и измерение мотивации\n\nМониторинг мотивации играет важную роль в управлении персоналом. Он позволяет выявить, насколько сотрудники мотивированы, и что можно сделать для улучшения этой мотивации. Для проведение мониторинга необходимо выполнить следующее:\n\n1. Определение ключевых показателей: Прежде всего, определите, какие аспекты мотивации важны для вашего ресторана. Это могут быть производительность, удовлетворенность работой, отсутствие текучести кадров и другие.\n\n2. Инструменты оценки мотивации:\n\nАнкеты и опросники: Создание анкет или опросников с вопросами о предпочтениях, ожиданиях и мотиваторах сотрудников. Опросники могут включать вопросы о том, какие виды вознаграждений или признания сотрудники ценят больше всего.\n\nИнтервью: Проведение интервью с сотрудниками, чтобы более подробно выяснить, что мотивирует их на работе. В ходе беседы можно задавать вопросы о прошлых работах, где они чувствовали себя наиболее мотивированными, и почему.\n\nОценка производительности: Анализ данных о производительности сотрудников может дать понимание, какие мотивационные факторы влияют на их работу. Сравнение производительности до и после внедрения мотивационных программ может быть информативным.\n\nАнализ текучести кадров: Исследование того, почему сотрудники уходят с работы, и какие факторы могли повлиять на их решение. Это может дать понимание о том, что следует улучшить в мотивации.\n\nОпросы и фокус-группы: Проведение опросов и фокус-групп среди сотрудников для выявления их мнения по вопросам мотивации и предложений по улучшению.\n\nВам может помочь в сборе информации создание опроса на предмет удовлетворенности работой в своем личном кабинете ServiceGuru.\n\nЕсли у вас есть потребность в анонимном опросе, то вы вполне можете создать анонимный опрос на гугл опросах, а к своему кабинету прикрепить ссылку на его прохождение для сотрудников.\n\n3. Анализ результатов: Собранные данные требуют анализа. Изучите, какие факторы влияют на мотивацию сотрудников, и определите, где существуют проблемы.\n\nУправление мотивацией в переменных ситуациях\n\nИногда условия труда в ресторане вынуждены изменяться в силу внутренних или внешних обстоятельств. Управление мотивацией в переменных ситуациях требует особых навыков и стратегий. Сотрудники могут быть подвержены стрессу и неуверенности, и важно уметь поддержать их мотивацию в таких моментах.\n\nВажные аспекты управления мотивацией в переменных ситуациях:\n\n1. Понимание и коммуникация: Первым шагом является честное и открытое общение с сотрудниками о переменных ситуациях. Они должны понимать, что происходит и как это может повлиять на работу и условия труда.\n\n2. Адаптация мотивационных стратегий: Время перемен требует адаптации мотивационных стратегий. Это может включать в себя более частые обратные связи, поддержку и увеличение прозрачности.\n\n3. Поддержка сотрудников: Время перемен может быть трудным для сотрудников. Предоставьте поддержку, как эмоциональную, так и практическую, чтобы помочь им справляться с неопределенностью.\n\nДолгосрочное управление мотивацией\n\nДолгосрочное управление мотивацией требует планирования и последовательности действий. Оно помогает сохранить высокий уровень мотивации сотрудников на протяжении длительного времени.\n\nВажные аспекты долгосрочного управления мотивацией:\n\n1. Установление долгосрочных целей: Определите, какие долгосрочные цели связаны с мотивацией сотрудников. Это может быть уменьшение текучести кадров, повышение производительности или улучшение клиентского опыта.\n\n2. Разработка мотивационных программ: Разработайте моивационные программы, которые будут способствовать достижению долгосрочных целей.\n\nВот несколько примеров таких программ:\n\n1.Система бонусов за производительность:\n\nВнедрение системы бонусов для сотрудников, основанных на их производительности. Это может включать в себя бонусы за достижение целей продаж, положительные отзывы гостей  или участие в программе лояльности.\n\n2.Обучение и развитие:\n\nПредоставление сотрудникам доступа к обучению и развитию, чтобы помочь им развивать свои навыки и продвинуться по карьерной лестнице. Это может включать в себя финансирование курсов, тренингов и сертификаций.\n\n5.Программа лояльности для сотрудников:\n\nЗапуск программы лояльности, которая предоставляет сотрудникам скидки или бонусы в ресторане, а также возможность участвовать в акциях и мероприятиях.\n\n6.Система карьерного роста:\n\nСоздание плана карьерного роста для сотрудников с возможностью продвижения по иерархии и развития навыков ресторанного бизнеса.\n\n7.Участие в принятии решений:\n\nВключение сотрудников в процесс принятия решений и обсуждение изменений, которые могут повлиять на их работу и рабочую среду.\n\n8.Соревнования и игры:\n\nОрганизация соревнований и игр между сотрудниками, которые могут стимулировать конкуренцию и увлечение работой.\n\n9.Мероприятия и корпоративные вечеринки:\n\nОрганизация разнообразных мероприятий и корпоративных вечеринок для создания позитивной рабочей атмосферы и укрепления команды.\n\n3. Регулярная оценка и коррекция: оценивайте результаты мотивационных программ и вносите коррекции, если необходимо. Долгосрочное управление мотивацией требует постоянного мониторинга и адаптации.\n\nДолгосрочное управление мотивацией способствует стабильной и высокой мотивации сотрудников, что важно для успешного ресторанного бизнеса. Желаем вам успешной практики и эффективного управления мотивацией в вашем ресторане!","images":["assets/remaining-courses/guru-43399-101486-0.jpg","assets/remaining-courses/guru-43399-101486-1.jpg","assets/remaining-courses/guru-43399-101486-2.jpg","assets/remaining-courses/guru-43399-101486-3.jpg","assets/remaining-courses/guru-43399-101486-4.jpg","assets/remaining-courses/guru-43399-101486-5.jpg","assets/remaining-courses/guru-43399-101486-6.jpg","assets/remaining-courses/guru-43399-101486-7.jpg"],"links":[],"id":"101486"},{"title":"Выходное интервью, как инструмент мотивации","text":"","images":["assets/remaining-courses/guru-43399-101487-0.jpg"],"links":[{"title":"Видео к уроку","url":"https://www.youtube.com/embed/E1WQltYXxmg?autoplay=0&mute=0&controls=1&origin=https%3A%2F%2Fmy.service.guru&playsinline=1&showinfo=0&rel=0&iv_load_policy=3&modestbranding=1&enablejsapi=1&widgetid=1&forigin=https%3A%2F%2Fmy.service.guru%2Femployee%2Fr%2Fcourses%2F43399%2Flesson%2F101487&aoriginsup=1&vf=1"}],"id":"101487"},{"title":"ServiceGuru и мотивация","text":"Как ServiceGuru помогает в построении систем мотивации.\n\nРазвитие профессиональных навыков не только мотивирует сотрудников, но и помогает ресторанам повысить качество обслуживания, что способствует удовлетворенности гостей. В этой части курса речь пойдет  о том, как  помогает в развитии сотрудников платформа ServiceGuru. На сегодняшний день она на предоставляет нам большое разнообразие мотивационных инструментов. Предлагаем вам некоторые из них:\n\nНа сегодняшний день она на предоставляет нам большое разнообразие мотивационных инструментов. Предлагаем вам некоторые из них:\n\n1. Треки обучения. Для реализации качественного обучения стажеров вы можете назначить индивидуальные треки обучения по должностям, выстроив курсы и уроки в нужной для прохождения последовательности и контролируя процесс их освоения.\n\n2. Платформа, как часть бонусной системы. В можете создать свою бонусную систему мотивации, связав ее с баллами на платформе ServiceGuru. Все сотрудники, проходя тестовые задания в курсах на разных уровнях сложности получают баллы. На базовом уровне -1 балл за верный ответ, на уровне эксперт - 2 балла, на уровне профи -3 балла. Таким образом выстроив индивидуальный путь сотрудника и зная, сколько баллов он может получить за его прохождение вы вполне можете включить их в его мотивацию и сделать дополнительным стимулом к быстрому обучению на платформе.\n\n3.Корпоративный портал - информирование о значимых достижениях через ленту новостей. Наш ленту новостей можно использовать, например, как информационную доску: вы можете подводить итоги месяца, хвалить лучших сотрудников, а также сообщать о важных изменениях в ресторане. Помимо этого ленту можно использовать и для  поддержания корпоративной культуры: так вы можете запланировать поздравления сотрудников с днем рождения и важными праздниками, а ServiceGuru опубликует их автоматически в назначенную вами дату.\n\n8. Создание программ лояльности. На платформе вы можете создавать и доводить до сотрудников корпоративные программы лояльности для сотрудников и гостей. Организовать такой функционал можно не только через вкладку учебные курсы, но и через раздел меню и стандарты: так самые важные аспекты корпоративных программ могут быть всегда под рукой у сотрудника\n\n9.Повышение обученности, как следствие продаж. Наша уникальная вкладка меню и стандарты помогает мотивировать ваших сотрудников на допродажи и повышение среднего чека. при создании каждого блюда вы можете добавить к нему в пару любое блюдо вашего ресторана и объявить по нему конкурс по продажам. Что не только повысить обученность сотрудников в фудпейринге, но и поможет поднять их мотивацию к продажам.\n\n7. Проведение конкурсов и соревнований. Кроме инструмента системы мотивации существующей, вы можете использовать нашу рейтинговую систему для проведения конкурсов и соревнований. Запускайте конкурсы на платформе сервис гуру, например, кто лучше всех сдаст тесты в курсах с первой попытки и наберет большее количество баллов за определенный срок(например месяц) тот получает приз.Снимайте рейтинги и объявляйте победителей. Поздравлять лидеров, как вы уже знаете можно также через раздел новостной ленты.\n\n4. Построение карьерного трека. Наша платформа это отличный инструмент для того, чтобы познакомить сотрудника с его карьерным треком описанием преимуществ и выгод. Вы можете разместить карьерные треки в разделе учебные курсы для каждой должности.\n\n5. Проведение встреч. Помощь в проведении  регулярных корпоративных видеовстреч, для обсуждения идей: ссылку на регистрацию можно разместить в библиотеке или сделать рассылку через новости.\n\n6: Выходное интервью. Реализация выходного интервью, как инструмента  пост анализа эффективности систем мотивации. Создайте автоназначаемый опрос на должность “Уволенный” и при переводе сотрудника на данную должность опрос будет назначен ему автоматически, а вы можете не тратить время на проведение выходного интервью.","images":["assets/remaining-courses/guru-43399-101488-0.jpg","assets/remaining-courses/guru-43399-101488-1.jpg","assets/remaining-courses/guru-43399-101488-2.jpg","assets/remaining-courses/guru-43399-101488-3.jpg","assets/remaining-courses/guru-43399-101488-4.jpg","assets/remaining-courses/guru-43399-101488-5.jpg","assets/remaining-courses/guru-43399-101488-6.jpg"],"links":[],"id":"101488"}],"outline":[{"type":"lesson","title":"Введение","lessonIndex":0},{"type":"lesson","title":"Основы мотивации в ресторанной индустрии","lessonIndex":1},{"type":"lesson","title":"Связь мотивации с производительностью","lessonIndex":2},{"type":"test","title":"Тест 1"},{"type":"test","title":"Тест 2"},{"type":"lesson","title":"Теории мотивации","lessonIndex":3},{"type":"test","title":"Тест 3"},{"type":"lesson","title":"Практические инструменты мотивации персонала","lessonIndex":4},{"type":"test","title":"Тест 4"},{"type":"lesson","title":"Оценка и управление мотивацией","lessonIndex":5},{"type":"lesson","title":"Выходное интервью, как инструмент мотивации","lessonIndex":6},{"type":"lesson","title":"ServiceGuru и мотивация","lessonIndex":7}],"testIds":["93157","93158","93159","93160"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
